    for (const [o, col, a] of [[0, '16,18,23', .8], [.18, '120,128,142', .6], [.32, '70,8,12', .75], [.44, '220,30,26', .85], [.5, '255,214,196', .9], [.56, '220,30,26', .85], [.68, '70,8,12', .75], [.82, '120,128,142', .6], [1, '16,18,23', .8]]) bg.addColorStop(o, 'rgba(' + col + ',' + (a*al0).toFixed(3) + ')');
