        const sg = c.createRadialGradient(X, Y, 0, X, Y, r); sg.addColorStop(0, 'rgba(176,180,188,' + (.8*al).toFixed(3) + ')'); sg.addColorStop(.55, 'rgba(118,122,130,' + (.55*al).toFixed(3) + ')'); sg.addColorStop(1, 'rgba(80,84,92,0)');
